/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */

// generated by: gemini-3.1-pro
// Disclaimer: I don't use C++ to solve leetcode problem
class Solution {
public:
    bool hasCycle(ListNode *head) {
        ListNode* curr = head;
        
        while (curr != nullptr) {
            // 將指標轉為整數型態以便進行位元運算
            uintptr_t next_ptr = reinterpret_cast<uintptr_t>(curr->next);
            
            // 檢查 LSB 是否為 1
            if (next_ptr & 1) {
                return true; // 發現迴圈
            }
            
            // 將目前的 next 指標加上「已訪問」標記 (LSB 設為 1)
            curr->next = reinterpret_cast<ListNode*>(next_ptr | 1);
            
            // 清除 LSB 以取得真實的下一個節點位址，繼續走訪
            curr = reinterpret_cast<ListNode*>(next_ptr & ~1UL);
        }
        
        return false; // 走到 nullptr，沒有迴圈
    }
};